const { TokenBucket } = require('./kova.js');
const assert = require('assert');

function test() {
  console.log("Running tests...");

  // 1. Basic functionality & Refill
  const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 1 });
  assert.strictEqual(bucket.available(), 10, "Should start full");

  // Test tryTake
  assert.strictEqual(bucket.tryTake(5), true, "Should take 5 tokens");
  assert.strictEqual(bucket.available(), 5, "Remaining tokens should be 5");
  assert.strictEqual(bucket.tryTake(6), false, "Should not take if insufficient");
  assert.strictEqual(bucket.available(), 5, "Tokens shouldn't change if tryTake fails");

  // Test Refill over time (simulated)
  let currentTime = 1000;
  const mockNow = () => currentTime;
  const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: mockNow });

  currentTime += 1000; // 1 second passed, should refill 2 tokens
  assert.strictEqual(bucket2.available(), 10, "Should be capped at capacity"); // Capacity is 10, we were at 10

  bucket2.tryTake(5); // tokens = 5
  currentTime += 1000; // 1 second passed, should refill 2 tokens. tokens = 7
  assert.strictEqual(bucket2.available(), 7, "Should refill correctly after 1s");

  // 2. Clock going backwards
  const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: mockNow });
  currentTime += 1000; // tokens = 10 + 1 (but capped at 10)
  bucket3.tryTake(5); // tokens = 5

  currentTime -= 500; // Clock went back!
  assert.strictEqual(bucket3.available(), 5, "Tokens should not decrease or increase if time goes back");

  currentTime += 1000; // From the LAST valid time (1000 + 1000 = 2000)
  // Wait, let's trace:
  // initial: now=1000, tokens=10, maxObserved=1000
  // time=2000: tokens=10, maxObserved=2000
  // tryTake(5): tokens=5
  // time=1500: maxObserved is 2000, so no refill. tokens=5.
  // time=2500: elapsed = 2500 - 2000 = 500ms. refill = (0.5 * 1) = 0.5. tokens = 5.5
  assert.strictEqual(bucket3.available(), 5.5, "Should use maxObservedTime for refills");

  // 3. msUntil
  const bucket4 = new TokenBucket({ capacity: 10, refillPerSecond: 2 }); // refills 1 token per 500ms
  bucket4.tryTake(8); // tokens = 2
  // Need 1 more token. 1 token takes 500ms.
  assert.strictEqual(bucket4.msUntil(3), 500, "msUntil should return 500ms for 1 token at 2 tokens/sec");
  assert.strictEqual(bucket4.msUntil(1), 0, "msUntil should return 0 if enough tokens exist");

  const bucket5 = new TokenBucket({ capacity: 10, refillPerSecond: 0 });
  bucket5.tryTake(5); // tokens = 5
  assert.strictEqual(bucket5.msUntil(6), Infinity, "msUntil should return Infinity if refill rate is 0");

  // 4. Error handling
  assert.throws(() => new TokenBucket({ capacity: -1, refillPerSecond: 1 }), RangeError);
  assert.throws(() => new TokenBucket({ capacity: 10, refillPerSecond: -1 }), RangeError);
  assert.throws(() => new TokenBucket({ capacity: 10, refillPerSecond: 1 }).tryTake(-1), RangeError);
  assert.throws(() => new TokenBucket({ capacity: 10, refillPerSecond: 1 }).msUntil(0), RangeError);

  console.log("All tests passed!");
}

