{"content":"const { TokenBucket } = require('./kova.js');
const assert = require('assert');

function runTests() {
  console.log('Running tests...');

  // Test 1: Temel dolum ve tryTake
  const bucket1 = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: () => 1000 });
  assert.strictEqual(bucket1.available(), 10, 'Initial tokens should be capacity');

  let currentTime = 1000;
  const getNow = () => currentTime;
  const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: getNow });

  currentTime += 1000; // 2 saniye geçti
  assert.strictEqual(bucket2.available(), 10, 'Should be capped at capacity'); // 10 + 2*2 = 14 -> 10

  bucket2.tryTake(5); // tokens = 5
  currentTime += 500; // 0.5 saniye geçti
  assert.strictEqual(bucket2.available(), 6, 'Should have 6 tokens (5 + 0.5*2)');

  // Test 2: Saat geri giderse
  const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: getNow });
  currentTime = 2000;
  bucket3.tryTake(5); // tokens = 5, maxObserved = 2000
  currentTime = 1500; // Saat geri gitti!
  assert.strictEqual(bucket3.available(), 5, 'Should not refill if time goes back');

  currentTime = 3000; // 3000 - 2000 = 1000ms -> 1 jeton
  assert.strictEqual(bucket3.available(), 6, 'Should refill relative to last observed time (2000)');

  // Test 3: msUntil
  const bucket4 = new TokenBucket({ capacity: 10, refillPerSecond: 1, now: getNow });
  currentTime = 1000;
  bucket4.tryTake(8); // tokens = 2
  // 8 token lazım, şu an 2 var. 6 token lazım.
  // Refill: 1 token/sec -> 6 token = 6000ms.
  assert.strictEqual(bucket4.msUntil(8), 6000);
  assert.strictEqual(bucket4.msUntil(2), 0);

  const bucket5 = new TokenBucket({ capacity: 10, refillPerSecond: 0, now: getNow });
  currentTime = 1000;
  bucket5.tryTake(5);
  assert.strictEqual(bucket5.msUntil(10), Infinity);

  // Test 4: Hata fırlatma
  assert.throws(() => new TokenBucket({ capacity: -1, refillPerSecond: 1 }), RangeError);
  assert.throws(() => new TokenBucket({ capacity: 10, refillPerSecond: -1 }), RangeError);
  assert.throws(() => bucket1.tryTake(-1), RangeError);

  console.log('All tests passed!');
}

runTests();
